sql(f"insert into alertas (workspace_id, chave, tipo, regra, severidade, titulo, mensagem, dia, resolvido_em) values ('{WS}', 't215:velho', 'repetido', 'sem_vendas', 'alta', 'Sem vendas', 'x', '2026-11-08', now())")
gid = sql(f"insert into guardrail_definicoes (workspace_id, nome, metrica, operador, limite, severidade) values ('{WS}', 'CPL máximo t215', 'cpl', 'max', 8, 'critico') returning id")
sql(f"insert into guardrail_alertas (workspace_id, guardrail_id, data, valor, limite, severidade, mensagem) values ('{WS}', '{gid}', '2026-11-09', 11.5, 8, 'critico', 'CPL de R$ 11,50 passou o limite de R$ 8,00.')")
d = DET()
chk(d['novos'] >= 6 and d['resolvidos'] == 0, 'primeira conferência: riscos novos, nada resolvido', d)
chk(R("fonte = 'metas' and metrica = 'faturamento'") == 'abaixo_do_esperado:empresa:alta:aberto,risco_de_nao_atingir:empresa:alta:aberto' or 'faturamento' in R("fonte = 'metas'") , 'faturamento de novembro: "abaixo do esperado" e "risco de não atingir" (empresa)', R("fonte = 'metas'"))
chk('marketing' in R("fonte = 'metas' and metrica = 'leads'"), 'leads de novembro: risco na área de marketing')
chk(sql(f"select count(*) from riscos where workspace_id = '{WS}' and fonte = 'metas' and chave like '%2026-01-01%'") == '0', 'o ano com meta só em novembro (cobertura parcial) não duplica os riscos do mês')
