chk(t.startswith('Alunos parados na jornada (3)|cs|3|3 aviso(s) em aberto. O mais recente (07/11)'), '3 alertas de aluno parado viram 1 risco de CS, com a contagem e o mais recente', t)
chk(R("chave = 'alerta:contas_vencidas'") == 'operacional:financeiro:media:aberto', 'contas vencidas: risco do financeiro')
chk(sql(f"select count(*) from riscos where workspace_id = '{WS}' and chave = 'alerta:sem_vendas'") == '0', 'alerta já resolvido não vira risco')
chk(R("fonte = 'guardrails'") == 'operacional:marketing:alta:aberto', 'guardrail crítico em aberto: risco alto de marketing')
ev = sql(f"select evidencia from riscos where workspace_id = '{WS}' and chave like 'meta:faturamento:empresa::2026-11-01:2026-11-30:projecao'")
chk('não é probabilidade' in ev and 'faltam R$ 30.000,00' in ev, 'evidência explica a projeção, o que falta e que não é probabilidade', ev)
