chk(R("chave = 'alerta:parado'") == 'operacional:cs:media:resolvido' and sql(f"select resolvido_por from riscos where workspace_id = '{WS}' and chave = 'alerta:parado'") == 'sistema', 'alertas resolvidos: o risco é resolvido pelo sistema')
sql(f"update alertas set resolvido_em = null where workspace_id = '{WS}' and chave = 't215:parado:0'")
d = DET()
chk(R("chave = 'alerta:parado'") == 'operacional:cs:media:aberto' and d['reabertos'] == 1 and sql(f"select titulo from riscos where workspace_id = '{WS}' and chave = 'alerta:parado'") == 'Alunos parados na jornada', 'a condição voltou: o risco reabre (agora com 1 aviso)')
chk(sql(f"select string_agg(evento, ',' order by em) from riscos_eventos e join riscos r on r.id = e.risco_id where r.workspace_id = '{WS}' and r.chave = 'alerta:parado'") == 'detectado,resolvido_sistema,reaberto', 'histórico do risco: detectado, resolvido pelo sistema, reaberto')
try:
    sql(f"select riscos_acao((select id from riscos where workspace_id = '{WS}' limit 1), 'resolvido')"); chk(False, 'sem login, riscos_acao recusa')
except Exception as e: chk('não encontrado' in str(e), 'sem login, ninguém mexe no risco de outro cliente')
